import { Component, Prop, Element, State, Host, h, Method } from "@stencil/core";
import { hasSlot } from "../../utils/slot";

/**
 * @since 2.2.2
 * @status stable
 *
 * @slot tools - Used to display copy and export buttons
 *
 * @part base - The component's base wrapper.
 * @part tools - The component's tools wrapper.
 * @part content - The component's content wrapper.
 * @part inline - The component's inline wrapper when inline prop is true.
 */

@Component({
  tag: "hbr-code-snippet",
  styleUrl: "code-snippet.scss",
  shadow: true,
})
export class CodeSnippet {
  @Element() host: HTMLElement;

  /** The code string display in the component */
  @Prop({ reflect: false }) code: string = "";

  /** Show the line number */
  @Prop({ reflect: true }) lineNumber: boolean = false;

  /** Turn on the inline mode */
  @Prop({ reflect: true }) inline: boolean = false;

  /** The max characters per line */
  @Prop({ reflect: true }) maxCharacters: number = 120;

  /** it's not turning on the syntax of the component, but to work with styling of syntax */
  @Prop({ reflect: true }) syntax: boolean = false;

  /** The size of the component */
  @Prop({ reflect: true }) size: "auto" | "small" | "medium" = "medium";
  @State() hasTools = false;

  constructor() {
    this.handleSlotChange = this.handleSlotChange.bind(this);
    this.copy = this.copy.bind(this);
  }
  handleSlotChange() {
    this.hasTools = hasSlot(this.host, "tools");
  }
  convertToHtml() {
    const lineNumberWidth = this.code.split("\n").length.toString().length
    return this.code.split("\n").map((line, idx) => {
      const maxCharacters = this.maxCharacters.toString()
      return (
        <span part="line" class="line" style={{ "--line-min-width": lineNumberWidth.toString() }}>
          {this.lineNumber ? <span part="line-number" class="line-number">{idx + 1}</span> : null}
          <span part="line-content" class="line-content" style={{ "--hbr-code-snippet-max-characters": maxCharacters }}>{line || <br></br>}</span>
        </span>
      );
    });
  }

  @Method()
  async copy(data) {
    try {
      await navigator.clipboard.writeText(data)
      return true;
    } catch (error) {
      console.error(error);
    }
  }
  @Method()
  async export(data, filename) {
    try {
      const blob = new Blob([data], { type: "plain/text" });
      const link = document.createElement("a");
      link.style.display = "none";
      link.href = URL.createObjectURL(blob);
      link.download = filename;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (error) {
      console.error(error);
    }
  }
  render() {
    const code = this.code ? this.convertToHtml() : null;
    return (
      <Host>
        {this.inline ? (
          <code part="inline" class={{
            "code-snippet--inline": true,
            "code-snippet--inline-small": this.size === "small",
            "code-snippet--inline-medium": this.size === "medium",
          }}><slot>{this.code}</slot><slot name="suffix"></slot></code>
        ) : (
          <div
            part="base"
            class={{
              "code-snippet": true,
              "code-snippet--tools": this.hasTools,
              "code-snippet--syntax": this.syntax,
              "code-snippet--small": this.size === "small",
              "code-snippet--medium": this.size === "medium",
            }}
          >
            <div
              part="tools"
              class={{
                "code-snippet__tools": true,
              }}
            >
              <slot name="tools" onSlotchange={this.handleSlotChange} />
            </div>
            <span part="content" class="code-snippet__content">
              <slot>
                <pre part="pre">
                  <code part="code">{code}</code>
                </pre>
              </slot>
            </span>
          </div>
        )}
      </Host>
    );
  }
}
